from produire import produire,paras,steps,table
from medicaments import carbomere
parts=[
('La {conjonctivite virale non herpétique} est une infection de la conjonctive, souvent liée à un adénovirus. Elle provoque rougeur, gêne et larmoiement. Une atteinte cornéenne peut compliquer l’évolution.',paras('La leçon ne couvre pas les infections herpétiques ou le zona oculaire, dont le traitement et les risques diffèrent. Une suspicion d’herpès demande un avis spécialisé.', 'La conjonctive tapisse la face interne des paupières et recouvre la sclère antérieure. La rougeur seule ne permet pas de distinguer une conjonctivite simple d’une inflammation plus profonde.')),
('Le {contexte de contage est fréquent}. Un épisode respiratoire ou un contact avec une personne atteinte peut orienter. Un œil peut être atteint avant le second.',paras('La forme virale est fréquente chez l’adulte et très contagieuse. Les proportions citées dans des synthèses ne sont pas des mesures de prévalence propres à la Suisse.', 'La transmission favorisée par les mains, les objets et les sécrétions justifie des mesures d’hygiène dans la famille comme au cabinet. Une atteinte bilatérale n’exclut pas une complication.')),
('Le {mécanisme associe infection de surface et inflammation}. La réaction conjonctivale produit larmoiement et inconfort. Une extension ou une réaction cornéenne peut modifier la vision.',paras('Certaines formes adénovirales s’accompagnent d’une kératoconjonctivite, avec opacités cornéennes et inflammation plus importante. Une membrane ou pseudomembrane peut nécessiter une prise en charge spécialisée.', 'Un antibiotique antibactérien ne traite pas le virus. La persistance d’une gêne ne doit pas conduire à multiplier les traitements sans réexaminer la cornée.')),
('Le {tri vérifie que la forme est simple}. Douleur importante, photophobie ou baisse visuelle impose un avis urgent. Lentilles, immunosuppression et chirurgie récente abaissent le seuil d’orientation.',paras('Une cornée trouble, un point blanc, un hypopion ou des lésions vésiculaires ne doivent pas être banalisés. Un nouveau-né avec rougeur et sécrétions relève d’un parcours urgent distinct.', 'L’absence de douleur marquée ne suffit pas sur un terrain avec sensibilité cornéenne réduite. En cas d’incertitude ou d’équipement insuffisant, adresser plutôt que conclure à une virose bénigne.')),
('L’{anamnèse recherche contage et signes associés}. Préciser début, latéralité, sécrétions et évolution de la vision. Demander infection respiratoire, contacts, lentilles et traitements déjà utilisés.',paras('La sensation de sable, les sécrétions aqueuses et l’atteinte successive des yeux sont évocatrices, sans être spécifiques. Rechercher prurit dominant évoquant l’allergie et sécrétions très abondantes suggérant une autre infection.', 'Demander antécédents d’herpès, zona, immunosuppression, chirurgie et exposition chimique. Des symptômes urogénitaux ou une évolution prolongée imposent d’envisager notamment chlamydia.')),
('L’{examen documente la vision et la cornée}. Comparer les deux yeux et examiner paupières, conjonctive et pupilles. Un examen de surface normal doit être interprété avec le contexte.',paras('Une rougeur diffuse, des sécrétions séreuses et une adénopathie préauriculaire peuvent orienter. Leur absence n’exclut pas une infection virale.', 'La lampe à fente et la fluorescéine permettent de mieux analyser une atteinte cornéenne. Une baisse visuelle persistante après nettoyage des sécrétions ne doit pas être attribuée automatiquement à la conjonctivite.')),
('L’{approche syndromique distingue les causes de rougeur}. Les sécrétions et le prurit orientent sans suffire. Douleur profonde et photophobie changent la priorité.',table(['Présentation','Hypothèse ou décision'],[['Gêne, larmoiement et contage.','Conjonctivite virale possible si absence d’alarme.'],['Prurit dominant, bilatéral, rhinite.','Allergie possible.'],['Sécrétions mucopurulentes, paupières collées.','Bactérie possible, sans preuve isolée.'],['Photophobie, baisse visuelle ou infiltrat.','Rechercher kératite ou uvéite ; avis urgent.'],['Vésicules ou zona.','Infection herpétique à évaluer spécifiquement.']])) ,
('Le {diagnostic est généralement clinique}. Aucun signe unique ne différencie sûrement une origine virale d’une origine bactérienne. L’évolution et l’absence de complication soutiennent le diagnostic.',paras('Il ne faut pas nommer adénovirus à partir de la seule couleur des sécrétions. Une évolution atypique, une forme sévère ou une menace cornéenne justifie de réouvrir le diagnostic.', 'Le diagnostic de conjonctivite virale non herpétique implique de ne pas méconnaître l’herpès. Des traitements efficaces pour une inflammation non infectieuse peuvent être dangereux dans ce contexte.')),
('Les {examens complémentaires sont ciblés}. Une forme simple ne demande pas systématiquement de prélèvement. Une évolution persistante ou sévère peut justifier une recherche microbiologique.',paras('Une PCR virale et une culture bactérienne peuvent être discutées lors d’une réévaluation, surtout si le diagnostic change les soins ou les mesures collectives. Le spécialiste décide les prélèvements nécessaires si la cornée est atteinte.', 'Ne pas retarder une orientation urgente pour obtenir un résultat de laboratoire. Une PCR positive ne dispense pas de vérifier la fonction visuelle et les complications.')),
('L’{algorithme combine soutien et surveillance}. Confirmer d’abord l’absence d’alarme. Donner ensuite un plan de soins et de retour précis.',steps('Vérifier vision, cornée, douleur, photophobie et terrain.', 'Si signe d’alarme, adresser en urgence sans essai prolongé de collyres.', 'Si forme simple probable, expliquer contagion, hygiène et traitement symptomatique.', 'Réévaluer si aggravation ou absence d’amélioration attendue.', 'Si persistance ou nouveau signe, rechercher autre agent ou complication.')),
('La {prise en charge suisse privilégie hygiène et soutien}. Compresses fraîches et lubrification peuvent soulager. Un antibiotique ne traite pas la cause virale.',paras('Le protocole HUG propose aussi un antiseptique local dans certaines conjonctivites infectieuses. NICE et le résumé britannique soulignent que la plupart des formes virales simples ne nécessitent pas d’antimicrobien ; aucun antibiotique systématique n’est déduit du diagnostic.', 'Si une sécheresse ou un film lacrymal altéré contribue à la gêne, la fenêtre suivante décrit un exemple suisse de lubrifiant. Elle ne constitue pas un traitement antiviral.', '@@MEDICAMENTS@@', 'Ne pas prescrire de corticoïde topique empirique. Une inflammation sévère ou des opacités cornéennes doivent être évaluées par l’ophtalmologue, qui décide d’un traitement adapté. Les antiviraux des infections herpétiques ne sont pas transposés à la conjonctivite adénovirale simple.')),
('La {prévention réduit la transmission}. Se laver les mains, éviter de toucher les yeux et ne pas partager serviettes ou collyres. Suspendre les lentilles pendant les symptômes.',paras('Les mesures au cabinet incluent prévention de la contamination des instruments et surfaces selon les procédures locales. L’embout d’un flacon ne doit pas toucher l’œil.', 'Les conditions de travail ou de collectivité sont adaptées au risque, au métier et aux règles locales. L’absence d’exclusion scolaire systématique dans une recommandation britannique n’est pas une règle suisse universelle.', 'Douleur, photophobie ou baisse visuelle imposent un retour urgent. Les délais indicatifs de résolution d’une à deux semaines ne justifient pas d’attendre devant une aggravation ; HUG recommande une réévaluation si absence de réponse à quarante-huit heures.')),
('Le {point clé} est de surveiller la cornée et la vision. Une infection souvent spontanément résolutive peut se compliquer. L’hygiène est un traitement de la transmission, pas un substitut au tri.',paras('La présence de larmoiement et de contage ne suffit pas à exclure une autre cause. Adapter la prise en charge à l’évolution et éviter l’antibiotique ou le corticoïde par réflexe.'))]
quiz=[('Quel virus est souvent impliqué ?','Un adénovirus.'),('L’herpès relève-t-il exactement de cette leçon ?','Non, il exige une démarche et un traitement spécifiques.'),('Une atteinte des deux yeux prouve-t-elle la bénignité ?','Non.'),('Un antibiotique traite-t-il l’adénovirus ?','Non.'),('La couleur des sécrétions identifie-t-elle le virus ?','Non.'),('Quel élément fonctionnel mesurer ?','La vision de chaque œil.'),('Que faire devant une photophobie nouvelle ?','Rechercher une atteinte cornéenne ou profonde et obtenir un avis urgent.'),('Une culture est-elle systématique ?','Non.'),('Une PCR positive exclut-elle une complication ?','Non.'),('Un corticoïde peut-il être donné sans examen spécialisé ?','Non.'),('Le lubrifiant est-il antiviral ?','Non.'),('Peut-on partager le flacon familial ?','Non.'),('Un délai habituel d’évolution autorise-t-il l’attente devant aggravation ?','Non.'),('Quelle prévention est centrale ?','Hygiène des mains et absence de partage des objets contaminés.')]
produire(1,parts,quiz,(1,2,3,4,6,11),carbomere)
